from taf.ul.ettf.logging.interface import logging as logging_lib
from taf.ul.ettf.scheduler.robot_policy_scheduler import Policy
from taf.ul.ettf.scheduler.robot_policy_trigger import Suite, Test

logging = logging_lib()

_SYSLOG_KEYWORDS = [logging.with_capturing_gnb_syslog,
                    logging.with_capturing_simulators_syslog]

_CONFIGS_KEYWORDS = [logging.with_gnb_swconfig_collection,
                     logging.with_simulator_swconfig_collection]

_SNAPSHOT_KEYWORDS_ON_FAILURE = [logging.with_gnb_snapshot_collection_on_failure,
                                 logging.with_simulator_snapshot_collection_on_failure]

_TSHARK_KEYWORDS = [logging.with_capturing_f1ap_messages,
                    logging.with_capturing_ue_specific_messages,
                    logging.with_capturing_cell_specific_messages,
                    logging.with_capturing_adminapi_infomodel_messages,
                    logging.with_traffic_messages_from_wts]

_EMIL_KEYWORDS = [logging.with_emil_logs_collection]


SOS_REPORT = [logging.with_sos_report_collection]


NO_LOGS = Policy(
    {
        Test: [],
        Suite: [],
    }
)

FULL_POLICY = Policy(
    {
        Test: _SYSLOG_KEYWORDS + _TSHARK_KEYWORDS,
        Suite: _CONFIGS_KEYWORDS + _SNAPSHOT_KEYWORDS_ON_FAILURE + SOS_REPORT
    }
)

EMIL_POLICY = Policy(
    {
        Test: [],
        Suite: [logging.with_emil_logs_collection],
    }
)

SYSLOGS_PER_TEST_CASE = Policy(
    {
        Test: _SYSLOG_KEYWORDS,
        Suite: [],
    }
)

SYSLOGS_PER_TEST_SUITE = Policy(
    {
        Test: [],
        Suite: _SYSLOG_KEYWORDS,
    }
)

CONFIGS_PER_TEST_CASE = Policy(
    {
        Test: _CONFIGS_KEYWORDS,
        Suite: [],
    }
)

CONFIGS_PER_TEST_SUITE = Policy(
    {
        Test: [],
        Suite: _CONFIGS_KEYWORDS,
    }
)

SNAPSHOTS_PER_TEST_CASE_ON_FAIL = Policy(
    {
        Test: _SNAPSHOT_KEYWORDS_ON_FAILURE,
        Suite: [],
    }
)

SNAPSHOTS_PER_TEST_SUITE_ON_FAIL = Policy(
    {
        Test: [],
        Suite: _SNAPSHOT_KEYWORDS_ON_FAILURE,
    }
)
